import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SearchBarGraphicProps = Record<string, any>;

const SearchIcon = ({ color }: { color: string }) => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="11" cy="11" r="8" />
    <line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
);

const VideoIcon = ({ color }: { color: string }) => (
  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M23 7l-7 5 7 5V7z" />
    <rect x="1" y="5" width="15" height="14" rx="2" ry="2" />
  </svg>
);

const ArticleIcon = ({ color }: { color: string }) => (
  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
    <polyline points="14 2 14 8 20 8" />
    <line x1="16" y1="13" x2="8" y2="13" />
    <line x1="16" y1="17" x2="8" y2="17" />
    <polyline points="10 9 9 9 8 9" />
  </svg>
);

const GlobeIcon = ({ color }: { color: string }) => (
  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10" />
    <line x1="2" y1="12" x2="22" y2="12" />
    <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
  </svg>
);

const SearchBarGraphic: React.FC<SearchBarGraphicProps> = ({
  backgroundColor = "#f9fafb",
  transparentBackground = false,
  durationInSeconds = 8,
  searchQuery = "AI Motion Graphics",
  results = [
    "Malloy Studio AI Motion Graphics video",
    "Malloy Studio AI Motion Graphics article",
    "Malloy Studio AI Motion Graphics website"
  ],
  highlightIndex = 2,
  primaryColor = "#2563eb",
  searchBarColor = "#ffffff",
  textColor = "#111827",
  mutedTextColor = "#6b7280",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Metrics
  const containerWidth = width * 0.55; // Approx 1050px on 1920x1080
  const searchBarHeight = 96;
  const resultItemHeight = 88;
  const resultsPadding = 16;
  const totalResultsHeight = (results.length * resultItemHeight) + (resultsPadding * 2);

  // Core Animations
  const searchBarScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const typingProgress = interpolate(frame, [20, 75], [0, searchQuery.length], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentChars = Math.round(typingProgress);
  const typedText = searchQuery.substring(0, currentChars);
  
  const showCursor = frame < 85 && Math.floor(frame / 15) % 2 === 0;

  const resultsDropdownSpring = spring({
    frame: frame - 90,
    fps,
    config: { damping: 16, mass: 0.8 },
  });

  const highlightSpring = spring({
    frame: frame - 140,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const getResultIcon = (text: string, isHighlighted: boolean) => {
    const lower = text.toLowerCase();
    const color = isHighlighted ? primaryColor : mutedTextColor;
    if (lower.includes("video")) return <VideoIcon color={color} />;
    if (lower.includes("article")) return <ArticleIcon color={color} />;
    return <GlobeIcon color={color} />;
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          paddingTop: height * 0.25,
          transition: "none",
        }}
      >
        <div style={{ width: containerWidth, position: "relative", transition: "none" }}>
          
          {/* Main Search Bar */}
          <div
            style={{
              width: "100%",
              height: searchBarHeight,
              backgroundColor: searchBarColor,
              borderRadius: searchBarHeight / 2,
              display: "flex",
              alignItems: "center",
              padding: "0 36px",
              boxShadow: "0 20px 40px -10px rgba(0,0,0,0.08), 0 10px 15px -5px rgba(0,0,0,0.04)",
              transform: `scale(${searchBarScale})`,
              transformOrigin: "center center",
              transition: "none",
              zIndex: 10,
              position: "relative",
            }}
          >
            <div style={{ opacity: searchBarScale, transform: `scale(${searchBarScale})`, display: "flex", alignItems: "center", transition: "none" }}>
              <SearchIcon color={primaryColor} />
            </div>
            
            <div
              style={{
                marginLeft: 24,
                fontSize: 36,
                color: textColor,
                fontWeight: 500,
                display: "flex",
                alignItems: "center",
                transition: "none",
                whiteSpace: "pre",
              }}
            >
              {typedText}
              <div
                style={{
                  width: 3,
                  height: 44,
                  backgroundColor: primaryColor,
                  marginLeft: 4,
                  opacity: showCursor ? 1 : 0,
                  transition: "none",
                }}
              />
            </div>
          </div>

          {/* Results Dropdown */}
          {resultsDropdownSpring > 0.01 && (
            <div
              style={{
                marginTop: 24,
                width: "100%",
                backgroundColor: searchBarColor,
                borderRadius: 32,
                overflow: "hidden",
                height: resultsDropdownSpring * totalResultsHeight,
                boxShadow: "0 25px 50px -12px rgba(0,0,0,0.1)",
                padding: `${resultsPadding}px 16px`,
                boxSizing: "border-box",
                display: "flex",
                flexDirection: "column",
                gap: 4,
                opacity: interpolate(resultsDropdownSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" }),
                transition: "none",
              }}
            >
              {results.map((result, index) => {
                const itemEntry = spring({
                  frame: frame - (105 + index * 8),
                  fps,
                  config: { damping: 14 },
                });

                const isTargetHighlight = index === highlightIndex;
                const isHighlighted = isTargetHighlight && highlightSpring > 0.5;
                
                const itemY = interpolate(itemEntry, [0, 1], [20, 0]);
                const itemOpacity = itemEntry;

                return (
                  <div
                    key={index}
                    style={{
                      height: resultItemHeight,
                      width: "100%",
                      display: "flex",
                      alignItems: "center",
                      padding: "0 24px",
                      position: "relative",
                      transform: `translateY(${itemY}px)`,
                      opacity: itemOpacity,
                      borderRadius: 20,
                      transition: "none",
                    }}
                  >
                    {/* Highlight Background */}
                    {isTargetHighlight && highlightSpring > 0 && (
                      <div
                        style={{
                          position: "absolute",
                          inset: 0,
                          backgroundColor: primaryColor,
                          opacity: highlightSpring * 0.08,
                          borderRadius: 20,
                          transform: `scale(${interpolate(highlightSpring, [0, 1], [0.95, 1])})`,
                          transition: "none",
                        }}
                      />
                    )}

                    {/* Left Accent Line for Highlight */}
                    {isTargetHighlight && highlightSpring > 0 && (
                      <div
                        style={{
                          position: "absolute",
                          left: 0,
                          top: "20%",
                          bottom: "20%",
                          width: 4,
                          backgroundColor: primaryColor,
                          borderTopRightRadius: 4,
                          borderBottomRightRadius: 4,
                          transform: `scaleY(${highlightSpring})`,
                          opacity: highlightSpring,
                          transition: "none",
                        }}
                      />
                    )}

                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 24,
                        position: "relative",
                        zIndex: 2,
                        transition: "none",
                      }}
                    >
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          width: 48,
                          height: 48,
                          borderRadius: 14,
                          backgroundColor: isHighlighted ? `${primaryColor}15` : `${mutedTextColor}15`,
                          transition: "none",
                        }}
                      >
                        {getResultIcon(result, isHighlighted)}
                      </div>
                      <span
                        style={{
                          fontSize: 30,
                          color: isHighlighted ? primaryColor : textColor,
                          fontWeight: isHighlighted ? 600 : 400,
                          letterSpacing: "-0.01em",
                          transition: "none",
                        }}
                      >
                        {result}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SearchBarGraphic;